package dev.aivillages.core.kernel.storage;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static dev.aivillages.core.kernel.storage.StorageResolutionTestSupport.*;
import static dev.aivillages.core.kernel.storage.StorageRegistry.*;
import static dev.aivillages.core.kernel.storage.StorageResolution.Status.*;
import static dev.aivillages.core.kernel.storage.StorageResolver.*;

class StorageResolverTest {
    @Test void adaDefaultAndBobFoodResolveAssignedStableIds(){var e=new Env();UUID a=e.add(10,"Ada stock",0,64,0,true),b=e.add(11,"Bob food",1,64,0,true);e.assign(ADA,Role.DEFAULT,a);e.assign(BOB,Role.FOOD,b);
        var defaults=Map.<String,Object>of("kind","DEFAULT","owner",Map.of("kind","NAMED","label","Ada"),"container_type","ANY_MVP");assertEquals(a,e.resolve(defaults,Permission.DEPOSIT).endpoint().storageId());assertEquals(b,e.resolve(role("Bob","FOOD"),Permission.WITHDRAW).endpoint().storageId());}
    @Test void visibleNamesakesClarifyButHiddenNamesakesDoNot(){var e=new Env();UUID a=e.add(10,"Straße",0,64,0,true),b=e.add(11,"STRASSE",1,64,0,true);assertEquals(CLARIFY,e.resolve(named("strasse"),Permission.DEPOSIT).status());var row=e.records.get(b);e.records.put(b,new StorageRegistry.Record(WORLD,b,row.label(),PUBLIC,Set.of(),List.of(),0,1,0,State.ACTIVE,row.adapterId()));e.refresh();assertEquals(a,e.resolve(named("strasse"),Permission.DEPOSIT).endpoint().storageId());}
    @Test void missingDefaultNeverPicksAnAvailableChest(){var e=new Env();e.add(10,"one",0,64,0,true);e.add(11,"two",1,64,0,true);assertEquals(CLARIFY,e.resolve(role("Ada","DEFAULT"),Permission.DEPOSIT).status());}
    @Test void exactUnicodeNamesNeverFuzzySelect(){var e=new Env();UUID a=e.add(10,"Café",0,64,0,true);assertEquals(StorageResolution.labelKey("Café"),StorageResolution.labelKey("Café"));assertEquals(a,e.resolve(named("CAFÉ"),Permission.DEPOSIT).endpoint().storageId());assertEquals(UNAVAILABLE,e.resolve(named("Cafe"),Permission.DEPOSIT).status());}
    @Test void nearestRequiresExplicitPublicGrantForFinalOperation(){var e=new Env();e.add(10,"private",0,64,0,false);UUID b=e.add(11,"public",2,64,0,true);assertEquals(b,e.resolve(nearest("CALLER"),Permission.DEPOSIT).endpoint().storageId());}
    @Test void capturedActorAndCallerAnchorsChooseDifferentEndpoints(){var e=new Env();UUID a=e.add(10,"near caller",0,64,0,true),b=e.add(11,"near actor",10,64,0,true);assertEquals(a,e.resolve(nearest("CALLER"),Permission.DEPOSIT).endpoint().storageId());assertEquals(b,e.resolve(nearest("ACTOR"),Permission.DEPOSIT).endpoint().storageId());}
    @Test void unloadedUnsupportedUnknownCapacityAndDeniedCannotWin(){var e=new Env();UUID a=e.add(10,"unloaded",0,64,0,true),b=e.add(11,"unsupported",1,64,0,true),c=e.add(12,"unknown",2,64,0,true),d=e.add(13,"denied",3,64,0,true),ok=e.add(14,"okay",4,64,0,true);e.unloaded.add(a);e.unsupported.add(b);e.capacity.put(c,Eligibility.UNKNOWN);e.nativeDenied.add(d);assertEquals(ok,e.resolve(nearest("CALLER"),Permission.DEPOSIT).endpoint().storageId());}
    @Test void discoveryUsesLoadedSixteenBlockRadiusAndFourVertical(){var e=new Env();e.add(10,"outside horizontal",17,64,0,true);e.add(11,"outside vertical",0,69,0,true);e.add(12,"outside circle",12,64,12,true);assertEquals(UNAVAILABLE,e.resolve(nearest("CALLER"),Permission.DEPOSIT).status());UUID b=e.add(13,"boundary",16,68,0,true);assertEquals(b,e.resolve(nearest("CALLER"),Permission.DEPOSIT).endpoint().storageId());}
    @Test void repeatedSameTickCannotEvadeSixteenRecordSlice(){var e=new Env();for(int i=0;i<17;i++)e.add(10+i,"stock"+i,0,64,0,true);var q=e.resolver.begin(SCOPE,selector(nearest("CALLER")),Permission.DEPOSIT);assertEquals(PENDING,q.step().status());int count=e.observations;assertEquals(16,count);assertEquals(PENDING,q.step().status());assertEquals(count,e.observations);e.tick.incrementAndGet();assertEquals(RESOLVED,q.step().status());}
    @Test void incompleteCandidateAndMetadataScansReturnUnknown(){var e=new Env();for(int i=0;i<129;i++)e.add(10+i,"stock"+i,0,64,0,true);assertEquals(UNKNOWN,e.resolve(nearest("CALLER"),Permission.DEPOSIT).status());e=new Env();for(int i=0;i<257;i++)e.add(10+i,"private"+i,0,64,0,false);assertEquals(UNKNOWN,e.resolve(named("absent"),Permission.DEPOSIT).status());}
    @Test void changedViewOrRegistryDuringScanCannotSelectPartialSubset(){for(boolean registry:new boolean[]{false,true}){var e=new Env();for(int i=0;i<17;i++)e.add(10+i,"stock"+i,0,64,0,true);var q=e.resolver.begin(SCOPE,selector(nearest("CALLER")),Permission.DEPOSIT);assertEquals(PENDING,q.step().status());if(registry)e.refresh();else e.revision++;e.tick.incrementAndGet();assertEquals(UNKNOWN,q.step().status());}}
    @Test void selectedConsumesOnlyServerOwnedMatchingWitness(){var e=new Env();UUID a=e.add(10,"selected",0,64,0,true);var selected=Map.<String,Object>of("kind","SELECTED","selection_id",SELECTION.toString(),"container_type","ANY_MVP");assertEquals(UNAVAILABLE,e.resolve(selected,Permission.DEPOSIT).status());e.selection(a,100,120,SCOPE,EPOCH);assertEquals(a,e.resolve(selected,Permission.DEPOSIT).endpoint().storageId());assertEquals(UNAVAILABLE,e.resolve(selected,Permission.DEPOSIT).status());assertEquals(3,e.consumes);}
    @Test void expiredForeignRestartedAndReplacedSelectionsFailClosed(){for(int i=0;i<5;i++){var e=new Env();UUID a=e.add(10,"selected",0,64,0,true);var scope=i==1?new StorageAccessPolicy.Scope(WORLD,EPOCH,id(999),ADA):SCOPE;e.selection(a,i==0?50:100,i==0?60:120,scope,i==2?id(999):EPOCH);if(i==3)e.selectionValid=false;var body=Map.<String,Object>of("kind","SELECTED","selection_id",i==4?id(999).toString():SELECTION.toString(),"container_type","ANY_MVP");assertEquals(UNAVAILABLE,e.resolve(body,Permission.DEPOSIT).status());}}
    @Test void boundEndpointRechecksScopePolicyIdentityAndTwoTickWindow(){var e=new Env();UUID a=e.add(10,"stock",0,64,0,true);var b=e.resolve(nearest("CALLER"),Permission.DEPOSIT).endpoint();assertTrue(b.current(SCOPE));assertEquals("STORAGE",b.wire().body().get("kind"));assertFalse(b.current(new StorageAccessPolicy.Scope(WORLD,EPOCH,id(900),ADA)));e.nativeDenied.add(a);assertFalse(b.current(SCOPE));e.nativeDenied.clear();e.tick.addAndGet(3);assertFalse(b.current(SCOPE));}
    @Test void finalNativeVetoDoesNotFallbackToSecondRankedStorage(){var e=new Env();e.add(10,"stock",0,64,0,true);e.add(11,"stock2",1,64,0,true);var nativePort=new NativePort(){public View view(StorageAccessPolicy.Scope s,long tick){return e.view(s,tick);}public Observation observe(StorageAccessPolicy.Scope s,StorageRegistry.Record r,Permission p,long tick){var o=e.observe(s,r,p,tick);if(e.observations==3)return new Observation(s,o.binding(),tick,true,true,Eligibility.UNKNOWN);return o;}};var resolver=new StorageResolver(()->e.snapshot,e.policy,nativePort,e,e.recipientResolver,e.tick::get);assertEquals(UNKNOWN,resolver.begin(SCOPE,selector(nearest("CALLER")),Permission.DEPOSIT).step().status());}
    @Test void visibleNamesakeWithUnknownCapacityStillClarifies(){var e=new Env();e.add(10,"stock",0,64,0,true);UUID b=e.add(11,"stock",1,64,0,true);e.capacity.put(b,Eligibility.UNKNOWN);assertEquals(CLARIFY,e.resolve(named("stock"),Permission.DEPOSIT).status());}
    @Test void depositOnlyNamedSelectionDoesNotRequireInspect(){var e=new Env();UUID a=e.add(10,"shared",0,64,0,true);var row=e.records.get(a);e.records.put(a,new StorageRegistry.Record(WORLD,a,row.label(),PUBLIC,Set.of(),List.of(new Grant(PUBLIC,Set.of(Permission.DEPOSIT))),0,1,0,State.ACTIVE,row.adapterId()));e.refresh();assertEquals(a,e.resolve(named("shared"),Permission.DEPOSIT).endpoint().storageId());assertEquals(UNAVAILABLE,e.resolve(named("shared"),Permission.INSPECT).status());}
    @Test void nonStorageLandmarksRemainUnsupportedAndMinLongAnchorIsRejected(){var e=new Env();assertEquals(UNSUPPORTED,e.resolver.unsupportedPlace().status());assertThrows(IllegalArgumentException.class,()->new Position(DIM,Long.MIN_VALUE,0,0));}
}
